data = {
 'updated_utc': datetime.now(timezone.utc).isoformat(),
 'device': 'Razer Phone 2 (aura, SDM845)',
 'baseline': 'v26 fingerprint-resource kernel / 6.18.2-aura-bringup1+',
 'scope': 'Non-cellular hardware audit. Working basics does not mean full qualification.',
 'evidence': ['test-runs/snapshot/apps-hardware-inventory.txt', 'port-status.json:hardware_progress', 'build/kali/compatibility-progress.json', 'build/kali/camera-completion-progress.json', 'build/kali/telefocus-progress.json', 'build/kali/fingerprint-progress.json', 'build/kali/native-storage-progress.json'],
 'hardware': [dict(zip(('feature','status','evidence_summary','remaining'), row)) for row in rows],
 'apps': 'Everyday stock apps, Phosh Mobile Settings and kali-linux-default installed; package health checks passed. Calculator launch visually verified. Full release image still needs rebuilding with these changes.',
 'suggested_order': ['Stock fingerprint secure account/enrollment integration', 'Camera OIS/flash and front-sensor diagnosis', 'Wi-Fi throughput and battery/suspend/reboot endurance', 'Ambient light/proximity, GNSS, USB host and application use of hardware codecs', 'Broader peripheral and NetHunter capability validation'],
}
snapshot = ROOT / 'build/kali/snapshot-progress.json'
if snapshot.exists():
    snap = json.loads(snapshot.read_text())
    data['historical_snapshot_reference'] = str(snapshot.relative_to(ROOT))
out = ROOT / 'build/kali/hardware-audit.json'
out.write_text(json.dumps(data, indent=2) + '\n', encoding='utf-8')
body = ''.join('<tr>' + ''.join('<td>' + escape(str(x)) + '</td>' for x in row.values()) + '</tr>' for row in data['hardware'])
html = '''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Razer Phone 2 hardware audit</title><style>body{font:16px/1.5 system-ui,sans-serif;margin:32px auto;padding:0 20px;max-width:1300px;color:#dfe7ed;background:#101820}h1{font-size:30px}p{max-width:900px;color:#c3d0d8}table{border-collapse:collapse;width:100%;background:#16232d}th,td{text-align:left;vertical-align:top;padding:14px;border-bottom:1px solid #354651}th{color:#78ddba}td:first-child{font-weight:650;width:15%}td:nth-child(2){width:15%;color:#ead99f}a{color:#78ddba}@media(max-width:700px){table,tbody,tr,td{display:block}thead{display:none}td:first-child,td:nth-child(2){width:auto}tr{margin-bottom:20px;border:1px solid #354651}td{border:0;padding:8px 12px}}</style><h1>Razer Phone 2 hardware audit</h1><p>Native Kali NetHunter Pro · v20 kernel #13 · 8 October 2026</p><p>Working basics means there is functional evidence, not that every mode is finished. SIM and telephony work remains deferred. The front-camera fault and unstable USB connector were present before this Linux work.</p><table><thead><tr><th>Hardware</th><th>Status</th><th>Evidence</th><th>Remaining work</th></tr></thead><tbody>''' + body + '</tbody></table><p>Evidence and machine-readable status: hardware-audit.json, adjacent to this report. No SIM changes or destructive storage tests were performed for this audit.</p></html>'
html=html.replace('v20 kernel #13 · 8 October 2026','v26 kernel · 9 October 2026')
(out.parent / 'hardware-audit.html').write_text(html, encoding='utf-8')
print(out)
